class Scratchpad{constructor(){this.modal=document.getElementById('scratchpad-modal');this.canvas=document.getElementById('scratchpad-canvas');this.ctx=this.canvas?this.canvas.getContext('2d'):null;this.isDrawing=false;this.mode='pen';this.penColor='#0071e3';this.penSize=2;this.init();}
init(){if(!this.canvas||!this.ctx)return;this.resizeCanvas();window.addEventListener('resize',()=>this.resizeCanvas());this.canvas.addEventListener('mousedown',(e)=>this.startDrawing(e));this.canvas.addEventListener('mousemove',(e)=>this.draw(e));this.canvas.addEventListener('mouseup',()=>this.stopDrawing());this.canvas.addEventListener('mouseleave',()=>this.stopDrawing());this.canvas.addEventListener('touchstart',(e)=>{e.preventDefault();const touch=e.touches[0];this.startDrawing(touch);});this.canvas.addEventListener('touchmove',(e)=>{e.preventDefault();const touch=e.touches[0];this.draw(touch);});this.canvas.addEventListener('touchend',()=>this.stopDrawing());const btnPen=document.getElementById('scratch-pen-btn');const btnEraser=document.getElementById('scratch-eraser-btn');const btnClear=document.getElementById('scratch-clear-btn');const tabDraw=document.getElementById('tab-scratch-draw');const tabNotes=document.getElementById('tab-scratch-notes');const viewDraw=document.getElementById('scratch-draw-view');const viewNotes=document.getElementById('scratch-notes-view');if(btnPen){btnPen.addEventListener('click',()=>{this.mode='pen';btnPen.classList.add('btn-primary');btnPen.classList.remove('btn-secondary');if(btnEraser){btnEraser.classList.remove('btn-primary');btnEraser.classList.add('btn-secondary');}});}
if(btnEraser){btnEraser.addEventListener('click',()=>{this.mode='eraser';btnEraser.classList.add('btn-primary');btnEraser.classList.remove('btn-secondary');if(btnPen){btnPen.classList.remove('btn-primary');btnPen.classList.add('btn-secondary');}});}
if(btnClear){btnClear.addEventListener('click',async()=>{const isId=(window.AppInstance?.currentLanguage||'id')==='id';const confirmed=await window.GlassDialog.show({title:isId?'Bersihkan Canvas?':'Clear Canvas?',text:isId?'Seluruh coretan pada kanvas akan dihapus permanen.':'All drawings on the canvas will be permanently removed.',icon:'danger',confirmText:isId?'Ya, Hapus':'Yes, Clear',cancelText:isId?'Batal':'Cancel',confirmType:'danger'});if(confirmed)this.clearCanvas();});}
if(tabDraw&&tabNotes&&viewDraw&&viewNotes){tabDraw.addEventListener('click',()=>{tabDraw.classList.add('active');tabNotes.classList.remove('active');viewDraw.style.display='flex';viewNotes.style.display='none';this.resizeCanvas();});tabNotes.addEventListener('click',()=>{tabNotes.classList.add('active');tabDraw.classList.remove('active');viewDraw.style.display='none';viewNotes.style.display='flex';});}}
resizeCanvas(){if(!this.canvas||!this.modal.classList.contains('active'))return;const rect=this.canvas.getBoundingClientRect();if(rect.width>0&&rect.height>0){const tempImage=this.ctx.getImageData(0,0,this.canvas.width,this.canvas.height);this.canvas.width=rect.width;this.canvas.height=rect.height;this.ctx.fillStyle='#ffffff';this.ctx.fillRect(0,0,this.canvas.width,this.canvas.height);try{this.ctx.putImageData(tempImage,0,0);}catch(e){}}}
getCoordinates(e){const rect=this.canvas.getBoundingClientRect();return{x:(e.clientX||e.pageX)-rect.left,y:(e.clientY||e.pageY)-rect.top};}
startDrawing(e){this.isDrawing=true;const pos=this.getCoordinates(e);this.ctx.beginPath();this.ctx.moveTo(pos.x,pos.y);}
draw(e){if(!this.isDrawing)return;const pos=this.getCoordinates(e);this.ctx.lineWidth=this.mode==='eraser'?16:this.penSize;this.ctx.lineCap='round';this.ctx.strokeStyle=this.mode==='eraser'?'#ffffff':this.penColor;this.ctx.lineTo(pos.x,pos.y);this.ctx.stroke();}
stopDrawing(){if(this.isDrawing){this.ctx.closePath();this.isDrawing=false;}}
clearCanvas(){if(!this.ctx||!this.canvas)return;this.ctx.fillStyle='#ffffff';this.ctx.fillRect(0,0,this.canvas.width,this.canvas.height);}
open(){if(this.modal){this.modal.classList.add('active');setTimeout(()=>this.resizeCanvas(),50);}}
close(){if(this.modal){this.modal.classList.remove('active');}}}
window.Scratchpad=Scratchpad;